  const EXAM_SETS = buildHardSets_AB(DP900_HARD, { D1:13, D2:11, D3:8, D4:14 }, 5);
const DOMAIN_SETS = Object.fromEntries(DOMAINS.map(d => [d.id, AB620_HARD.filter(q => q.d === d.id)]));
const SET_READY = { 1: true, 2: true, 3: true, 4: true, 5: true };
const EXAM_TOTAL = Object.values(EXAM_SETS).reduce((s, x) => s + x.length, 0);

