            <span><span style={{ background: d.hue, color: nvInk("#ffffff", d.hue), borderRadius: 4, padding: "1px 6px", fontSize: 11, marginRight: 6, fontWeight: 700 }}>{d.id}</span>{domName(d.id, lang)}</span>
